CREATE SCHEMA tl;
CREATE SCHEMA api;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS cube;
CREATE EXTENSION IF NOT EXISTS earthdistance;
DO $$ BEGIN
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='throughline_app') THEN CREATE ROLE throughline_app LOGIN; END IF;
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='throughline_reader') THEN CREATE ROLE throughline_reader LOGIN; END IF;
END $$;
CREATE TABLE tl.channels(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name text UNIQUE NOT NULL,plugin text NOT NULL,description text DEFAULT '',fields jsonb DEFAULT '[]',is_reference boolean DEFAULT false,is_outside boolean DEFAULT false,conversation_gap_s int DEFAULT 1800,location_tolerance_s int DEFAULT 600,created_at timestamptz DEFAULT now());
CREATE TABLE tl.people(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,handle text UNIQUE NOT NULL,display_name text,is_owner boolean DEFAULT false,status text DEFAULT 'active',note text,merged_into bigint REFERENCES tl.people,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX one_owner ON tl.people(is_owner) WHERE is_owner;
CREATE TABLE tl.person_names(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,person_id bigint REFERENCES tl.people,name text NOT NULL);
CREATE TABLE tl.identifier_schemes(system text,kind text,same_system text,same_kind text,normalizer text CHECK(normalizer IN ('phone','email','trim','lower')),PRIMARY KEY(system,kind));
CREATE TABLE tl.identifiers(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,person_id bigint REFERENCES tl.people,system text,kind text,value text,value_norm text,status text DEFAULT 'confirmed' CHECK(status IN ('confirmed','suspected','ignored')),label text,asserted_by text,evidence jsonb DEFAULT '{}',created_at timestamptz DEFAULT now(),UNIQUE(system,kind,value_norm));
CREATE TABLE tl.fact_keys(key text PRIMARY KEY);
CREATE TABLE tl.facts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,person_id bigint REFERENCES tl.people,key text REFERENCES tl.fact_keys,value jsonb,asserted_by text);
CREATE TABLE tl.relation_kinds(kind text PRIMARY KEY,inverse text NOT NULL);
CREATE TABLE tl.relations(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,from_id bigint REFERENCES tl.people,to_id bigint REFERENCES tl.people,kind text REFERENCES tl.relation_kinds,asserted_by text);
CREATE TABLE tl.identity_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,operation text,asserted_by text,detail jsonb,at timestamptz DEFAULT now());
CREATE TABLE tl.threads(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,channel_id bigint REFERENCES tl.channels,external_id text,title text,metadata jsonb DEFAULT '{}',UNIQUE(channel_id,external_id));
CREATE TABLE tl.messages(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,channel_id bigint NOT NULL REFERENCES tl.channels,external_id text NOT NULL,version int NOT NULL,superseded_by bigint REFERENCES tl.messages,thread_id bigint REFERENCES tl.threads,thread_no int,happened_at timestamptz NOT NULL,happened_offset_min int,ended_at timestamptz,ingested_at timestamptz DEFAULT now(),author_handle text,author_identifier_id bigint REFERENCES tl.identifiers,person_id bigint REFERENCES tl.people,content text NOT NULL CHECK(length(trim(content))>0),images jsonb DEFAULT '[]',fields jsonb DEFAULT '{}',lat double precision,lon double precision,loc_accuracy_m real,loc_method text CHECK(loc_method IN ('source','track')),loc_reason text,access_label text,payload_hash text NOT NULL,tsv tsvector GENERATED ALWAYS AS (to_tsvector('english',content)) STORED,UNIQUE(channel_id,external_id,version));
CREATE INDEX messages_thread ON tl.messages(thread_id,happened_at,external_id) WHERE superseded_by IS NULL;
CREATE INDEX messages_search ON tl.messages USING gin(tsv);
CREATE INDEX messages_earth ON tl.messages USING gist(ll_to_earth(lat,lon)) WHERE lat IS NOT NULL;
CREATE TABLE tl.raw_payloads(message_id bigint PRIMARY KEY REFERENCES tl.messages,payload jsonb NOT NULL);
CREATE TABLE tl.location_track(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,at timestamptz NOT NULL,lat double precision NOT NULL,lon double precision NOT NULL,accuracy_m real,source text NOT NULL,UNIQUE(source,at));
CREATE INDEX track_time ON tl.location_track(at);
CREATE TABLE tl.entities(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,kind text NOT NULL,name text,external_ref text,is_placeholder boolean DEFAULT false,merged_into bigint REFERENCES tl.entities,metadata jsonb DEFAULT '{}',UNIQUE(kind,external_ref));
CREATE TABLE tl.links(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,type text NOT NULL,from_kind text NOT NULL,from_id bigint NOT NULL,to_kind text NOT NULL,to_id bigint NOT NULL,confidence real DEFAULT 1,method text DEFAULT 'source' CHECK(method IN ('source','rule','model','owner')),evidence jsonb DEFAULT '{}',job text,job_version text,status text DEFAULT 'active',created_at timestamptz DEFAULT now());
CREATE TABLE tl.plugins(name text PRIMARY KEY,manifest jsonb DEFAULT '{}',interval_s int DEFAULT 3600,last_success_at timestamptz,last_error text,messages_ingested bigint DEFAULT 0,updated_at timestamptz DEFAULT now());
CREATE TABLE tl.plugin_cursors(plugin text,key text,cursor jsonb,updated_at timestamptz DEFAULT now(),PRIMARY KEY(plugin,key));
CREATE TABLE tl.tokens(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name text,token_hash text UNIQUE NOT NULL,kind text CHECK(kind IN ('owner','agent','plugin')),plugin text,askers text[] DEFAULT '{}',revoked_at timestamptz);
CREATE TABLE tl.audit_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,token_id bigint REFERENCES tl.tokens,asker text,statement text,row_count int,at timestamptz DEFAULT now());
CREATE FUNCTION tl.immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF current_setting('throughline.purge',true)='on' AND current_user NOT IN ('throughline_app','throughline_reader') AND session_user NOT IN ('throughline_app','throughline_reader') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'ground truth cannot be deleted'; END IF;
 IF TG_TABLE_NAME!='messages' OR (to_jsonb(NEW)-ARRAY['superseded_by','thread_no','lat','lon','loc_accuracy_m','loc_method','loc_reason','author_identifier_id','person_id','tsv']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['superseded_by','thread_no','lat','lon','loc_accuracy_m','loc_method','loc_reason','author_identifier_id','person_id','tsv']) THEN RAISE EXCEPTION 'ground truth is immutable'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON tl.messages FOR EACH ROW EXECUTE FUNCTION tl.immutable();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON tl.raw_payloads FOR EACH ROW EXECUTE FUNCTION tl.immutable();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON tl.location_track FOR EACH ROW EXECUTE FUNCTION tl.immutable();
CREATE VIEW api.message_versions AS SELECT m.*,c.name AS channel,c.is_reference,c.is_outside,t.external_id AS thread_external_id,t.title AS thread_title,p.handle AS person_handle,p.display_name FROM tl.messages m JOIN tl.channels c ON c.id=m.channel_id LEFT JOIN tl.threads t ON t.id=m.thread_id LEFT JOIN tl.people p ON p.id=m.person_id;
CREATE VIEW api.messages AS SELECT * FROM api.message_versions WHERE superseded_by IS NULL;
CREATE VIEW api.relations AS SELECT id,from_id,to_id,kind,asserted_by FROM tl.relations UNION ALL SELECT r.id,r.to_id,r.from_id,k.inverse,r.asserted_by FROM tl.relations r JOIN tl.relation_kinds k USING(kind);
DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['threads','channels','people','identifiers','person_names','facts','entities','links','location_track','plugins'] LOOP EXECUTE format('CREATE VIEW api.%I AS SELECT * FROM tl.%I',n,n); END LOOP; END $$;
CREATE VIEW api.places AS SELECT * FROM api.entities WHERE kind='place';
CREATE VIEW api.visits AS SELECT * FROM api.messages WHERE channel='visits';
CREATE FUNCTION api.context(message_id bigint,before int DEFAULT 3,after int DEFAULT 3) RETURNS SETOF api.messages LANGUAGE sql STABLE AS $$ SELECT m.* FROM api.messages m JOIN api.messages a ON a.id=message_id AND m.thread_id=a.thread_id WHERE m.thread_no BETWEEN a.thread_no-greatest(before,0) AND a.thread_no+greatest(after,0) ORDER BY m.thread_no $$;
CREATE FUNCTION api.search_all(query text,max_results int DEFAULT 20) RETURNS TABLE(message jsonb,score real) LANGUAGE sql STABLE AS $$ SELECT to_jsonb(m),ts_rank_cd(m.tsv,websearch_to_tsquery('english',query)) score FROM api.messages m WHERE m.tsv @@ websearch_to_tsquery('english',query) ORDER BY score DESC,m.id LIMIT max_results $$;
CREATE FUNCTION api.search(query text,max_results int DEFAULT 20) RETURNS TABLE(message jsonb,score real) LANGUAGE sql STABLE AS $$ SELECT to_jsonb(m),ts_rank_cd(m.tsv,websearch_to_tsquery('english',query)) score FROM api.messages m WHERE NOT m.is_reference AND m.tsv @@ websearch_to_tsquery('english',query) ORDER BY score DESC,m.id LIMIT max_results $$;
CREATE FUNCTION api.near(lat double precision,lon double precision,meters double precision) RETURNS SETOF api.messages LANGUAGE sql STABLE AS $$ SELECT m.* FROM api.messages m WHERE earth_box(ll_to_earth(lat,lon),meters) @> ll_to_earth(m.lat,m.lon) AND earth_distance(ll_to_earth(lat,lon),ll_to_earth(m.lat,m.lon))<=meters $$;
CREATE FUNCTION api.near_place(name text,meters double precision) RETURNS SETOF api.messages LANGUAGE sql STABLE AS $$ SELECT m.* FROM api.places p CROSS JOIN LATERAL api.near((p.metadata->>'lat')::float8,(p.metadata->>'lon')::float8,meters) m WHERE p.name=near_place.name $$;
CREATE FUNCTION api.overlapping("from" timestamptz,"to" timestamptz) RETURNS SETOF api.messages LANGUAGE sql STABLE AS $$ SELECT * FROM api.messages WHERE happened_at<="to" AND coalesce(ended_at,happened_at)>="from" $$;
CREATE FUNCTION api.during(message_id bigint) RETURNS SETOF api.messages LANGUAGE sql STABLE AS $$ SELECT m.* FROM api.messages a CROSS JOIN LATERAL api.overlapping(a.happened_at,coalesce(a.ended_at,a.happened_at)) m WHERE a.id=message_id $$;
CREATE FUNCTION api.person(query text) RETURNS SETOF api.people LANGUAGE sql STABLE AS $$ SELECT DISTINCT p.* FROM api.people p LEFT JOIN api.person_names n ON n.person_id=p.id LEFT JOIN api.identifiers i ON i.person_id=p.id WHERE p.handle=query OR p.display_name=query OR n.name=query OR i.value=query OR i.value_norm=query $$;
CREATE FUNCTION api.person_messages(person_id bigint) RETURNS SETOF api.messages LANGUAGE sql STABLE AS $$ SELECT * FROM api.messages m WHERE m.person_id=person_messages.person_id $$;
CREATE FUNCTION api.follow(kind text,id bigint,link_type text DEFAULT NULL,depth int DEFAULT 1) RETURNS TABLE(kind text,id bigint,depth int) LANGUAGE sql STABLE AS $$ WITH RECURSIVE walk(kind,id,depth,path) AS (SELECT follow.kind,follow.id,0,ARRAY[follow.kind||':'||follow.id] UNION ALL SELECT CASE WHEN l.from_kind=w.kind AND l.from_id=w.id THEN l.to_kind ELSE l.from_kind END,CASE WHEN l.from_kind=w.kind AND l.from_id=w.id THEN l.to_id ELSE l.from_id END,w.depth+1,w.path||CASE WHEN l.from_kind=w.kind AND l.from_id=w.id THEN l.to_kind||':'||l.to_id ELSE l.from_kind||':'||l.from_id END FROM walk w JOIN api.links l ON ((l.from_kind=w.kind AND l.from_id=w.id) OR (l.to_kind=w.kind AND l.to_id=w.id)) WHERE w.depth<follow.depth AND l.status='active' AND (link_type IS NULL OR l.type=link_type) AND NOT (CASE WHEN l.from_kind=w.kind AND l.from_id=w.id THEN l.to_kind||':'||l.to_id ELSE l.from_kind||':'||l.from_id END=ANY(w.path))) SELECT DISTINCT kind,id,depth FROM walk WHERE depth>0 $$;
CREATE FUNCTION api.catalog() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('channels',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM api.channels c),'views',(SELECT jsonb_agg(jsonb_build_object('name',table_name,'example','SELECT * FROM api.'||quote_ident(table_name)||' LIMIT 10')) FROM information_schema.views WHERE table_schema='api'),'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_arguments(p.oid),'example','SELECT * FROM api.'||p.proname||'(...)')) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='api'),'link_types',(SELECT coalesce(jsonb_agg(DISTINCT type),'[]') FROM api.links)) $$;
REVOKE ALL ON SCHEMA tl FROM PUBLIC;
GRANT USAGE ON SCHEMA tl,api TO throughline_app;
GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA tl TO throughline_app;
REVOKE UPDATE ON tl.messages,tl.raw_payloads,tl.location_track,tl.tokens FROM throughline_app;
REVOKE INSERT ON tl.tokens FROM throughline_app;
GRANT UPDATE(superseded_by,thread_no,lat,lon,loc_accuracy_m,loc_method,loc_reason,author_identifier_id,person_id) ON tl.messages TO throughline_app;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA tl TO throughline_app;
GRANT USAGE ON SCHEMA api TO throughline_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA api TO throughline_app,throughline_reader;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA tl FROM PUBLIC;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA api TO throughline_reader,throughline_app;
ALTER ROLE throughline_reader SET default_transaction_read_only=on;
ALTER ROLE throughline_reader SET statement_timeout='30s';
